import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Gudang gudang = new Gudang(Map.of("kopi", 10));
        AtomicInteger berhasil = new AtomicInteger();
        List<Thread> kasir = new ArrayList<>();
        for (int i = 0; i < 2; i++) {
            kasir.add(new Thread(() -> {
                if (gudang.ambil("kopi", 6)) {
                    berhasil.incrementAndGet();
                }
            }));
        }
        for (Thread t : kasir) {
            t.start();
        }
        for (Thread t : kasir) {
            t.join();
        }
        System.out.println("Berhasil " + berhasil.get() + ", sisa " + gudang.sisa());
    }
}

