import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner in = new Scanner(System.in);
        Map<String, Integer> omzet = new ConcurrentHashMap<>();
        List<Thread> kasir = new ArrayList<>();
        while (in.hasNextLine()) {
            String[] d = in.nextLine().trim().split(" ");
            kasir.add(new Thread(() -> {
                Jeda.ms(50);
                omzet.merge(d[0], Integer.parseInt(d[1]), Integer::sum);
            }));
        }
        for (Thread t : kasir) {
            t.start();
        }
        for (Thread t : kasir) {
            t.join();
        }
        System.out.println(new TreeMap<>(omzet));
    }
}

